    sorted, each road listed once.

    Example:
        critical_roads([("A", "B", 1), ("B", "C", 1), ("C", "A", 1), ("C", "D", 4)]) == [("C", "D")]
    """
    edge_list = list(edges)

    # Count occurrences of each undirected edge to handle parallel roads
    # As per design note: if multiple roads exist between same pair, none are critical.
    edge_counts = {}
    for u, v, _ in edge_list:
        if u == v: 
            continue
        pair = tuple(sorted((u, v)))
        edge_counts[pair] = edge_counts.get(pair, 0) + 1

    critical_pairs = set()

