import heapq
from itertools import permutations
from typing import List, Mapping, Optional, Sequence, Tuple

def _sp(adj, src, dst):
    pq = [(0, [src])]
    vis = {}
    while pq:
        c, p = heapq.heappop(pq)
        n = p[-1]
        if n == dst: return c, p
        if n in vis and vis[n] < c: continue
        vis[n] = c
        for nxt, w in adj.get(n, {}).items():
            heapq.heappush(pq, (c + w, p + [nxt]))
    return None

def plan_drop_route(adj: Mapping[str, Mapping[str, int]], origin: str, destination: str, drops: Sequence[str]) -> Optional[Tuple[int, List[str]]]:
    if len(set(drops)) != len(drops): raise ValueError("duplicates")
    if len(drops) > 6: raise ValueError("too many")
    for n in (origin, destination) + tuple(drops):
        if n not in adj: raise KeyError(n)
    best_c, best_p = float('inf'), None
    for p_drops in permutations(drops):
        curr_c, curr_p, possible = 0, [origin], True
        nodes = [origin] + list(p_drops) + [destination]
        for i in range(len(nodes)-1):
